INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('seed-video-ted-share-a-recipe','video-ted-share-a-recipe','Why You Should Share a Recipe with a Stranger (TED)',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,1,'tu6tF-lVDJI',NULL,'[{"i":0,"start":3.69,"end":7.48,"text":"Can we eat our way to a stronger democracy?","vi":"Liệu chúng ta có thể củng cố nền dân chủ thông qua việc ăn uống không?","ipa":null,"blanks":[],"words":[{"w":"Can","s":3.84,"e":4.08,"sp":0},{"w":"we","s":4.08,"e":4.3199997,"sp":0},{"w":"eat","s":4.3199997,"e":4.64,"sp":0},{"w":"our","s":4.64,"e":4.96,"sp":0},{"w":"way","s":4.96,"e":5.52,"sp":0},{"w":"to","s":5.52,"e":5.8399997,"sp":0},{"w":"a","s":5.8399997,"e":6,"sp":0},{"w":"stronger","s":6,"e":6.3999996,"sp":0},{"w":"democracy?","s":6.3999996,"e":7.28,"sp":0}],"alts":null},{"i":1,"start":9.29,"end":17.195,"text":"Normally, when we talk about strengthening democracy, we talk voting, town halls, civic engagement.","vi":"Thông thường, khi nói về việc củng cố dân chủ, chúng ta thường nhắc đến bỏ phiếu, các buổi họp dân và sự tham gia của cộng đồng.","ipa":null,"blanks":[],"words":[{"w":"Normally,","s":9.44,"e":10.16,"sp":0},{"w":"when","s":10.8,"e":10.96,"sp":0},{"w":"we","s":10.96,"e":11.12,"sp":0},{"w":"talk","s":11.12,"e":11.44,"sp":0},{"w":"about","s":11.44,"e":11.679999,"sp":0},{"w":"strengthening","s":11.679999,"e":12.16,"sp":0},{"w":"democracy,","s":12.16,"e":13.04,"sp":0},{"w":"we","s":13.04,"e":13.12,"sp":0},{"w":"talk","s":13.12,"e":13.5199995,"sp":0},{"w":"voting,","s":13.5199995,"e":14.32,"sp":0},{"w":"town","s":14.639999,"e":14.96,"sp":0},{"w":"halls,","s":14.96,"e":15.44,"sp":0},{"w":"civic","s":15.795,"e":16.195,"sp":0},{"w":"engagement.","s":16.195,"e":16.994999,"sp":0}],"alts":null},{"i":2,"start":17.325,"end":22.635,"text":"All of that matters. But I''d like to suggest something unexpected.","vi":"Tất cả những điều đó đều quan trọng. Nhưng tôi muốn đề xuất một điều gì đó bất ngờ hơn.","ipa":null,"blanks":[],"words":[{"w":"All","s":17.475,"e":17.715,"sp":0},{"w":"of","s":17.715,"e":17.875,"sp":0},{"w":"that","s":17.875,"e":18.035,"sp":0},{"w":"matters.","s":18.035,"e":18.755,"sp":0},{"w":"But","s":19.155,"e":19.395,"sp":0},{"w":"I''d","s":19.395,"e":19.635,"sp":0},{"w":"like","s":19.635,"e":19.795,"sp":0},{"w":"to","s":19.795,"e":19.955,"sp":0},{"w":"suggest","s":19.955,"e":20.355,"sp":0},{"w":"something","s":20.355,"e":21.075,"sp":0},{"w":"unexpected.","s":21.315,"e":22.435,"sp":0}],"alts":null},{"i":3,"start":23.085,"end":32.5,"text":"Food. Food may be as essential to a strong democracy if we accept two simple ideas.","vi":"Đó là ẩm thực. Ẩm thực có thể thiết yếu đối với một nền dân chủ vững mạnh nếu chúng ta chấp nhận hai ý tưởng đơn giản.","ipa":null,"blanks":[],"words":[{"w":"Food.","s":23.235,"e":23.955,"sp":0},{"w":"Food","s":24.435,"e":24.835,"sp":0},{"w":"may","s":25.715,"e":26.035,"sp":0},{"w":"be","s":26.035,"e":26.195,"sp":0},{"w":"as","s":26.195,"e":26.595001,"sp":0},{"w":"essential","s":26.595001,"e":27.395,"sp":0},{"w":"to","s":27.395,"e":27.715,"sp":0},{"w":"a","s":27.715,"e":27.955,"sp":0},{"w":"strong","s":27.955,"e":28.355,"sp":0},{"w":"democracy","s":28.355,"e":29.154999,"sp":0},{"w":"if","s":29.66,"e":29.98,"sp":0},{"w":"we","s":29.98,"e":30.14,"sp":0},{"w":"accept","s":30.14,"e":30.46,"sp":0},{"w":"two","s":30.46,"e":30.94,"sp":0},{"w":"simple","s":30.94,"e":31.5,"sp":0},{"w":"ideas.","s":31.5,"e":32.3,"sp":0}],"alts":{"13":["2"]}},{"i":4,"start":32.71,"end":37.084,"text":"First, democracy relies upon us knowing each other,","vi":"Thứ nhất, dân chủ dựa vào việc chúng ta hiểu biết lẫn nhau,","ipa":null,"blanks":[],"words":[{"w":"First,","s":32.86,"e":33.579998,"sp":0},{"w":"democracy","s":34.14,"e":34.7,"sp":0},{"w":"relies","s":34.7,"e":35.26,"sp":0},{"w":"upon","s":35.26,"e":35.58,"sp":0},{"w":"us","s":35.58,"e":35.82,"sp":0},{"w":"knowing","s":35.82,"e":36.22,"sp":0},{"w":"each","s":36.22,"e":36.46,"sp":0},{"w":"other,","s":36.46,"e":36.94,"sp":0}],"alts":null},{"i":5,"start":37.116,"end":43.54,"text":"being able to talk to one another, understanding that disagreement does not make someone an enemy.","vi":"có thể trò chuyện với nhau, và hiểu rằng sự bất đồng không biến ai đó thành kẻ thù.","ipa":null,"blanks":[],"words":[{"w":"being","s":37.26,"e":37.5,"sp":0},{"w":"able","s":37.5,"e":37.66,"sp":0},{"w":"to","s":37.66,"e":37.82,"sp":0},{"w":"talk","s":37.82,"e":38.14,"sp":0},{"w":"to","s":38.14,"e":38.3,"sp":0},{"w":"one","s":38.3,"e":38.46,"sp":0},{"w":"another,","s":38.46,"e":39.1,"sp":0},{"w":"understanding","s":39.34,"e":39.9,"sp":0},{"w":"that","s":39.9,"e":40.22,"sp":0},{"w":"disagreement","s":40.22,"e":41.1,"sp":0},{"w":"does","s":41.1,"e":41.42,"sp":0},{"w":"not","s":41.42,"e":41.739998,"sp":0},{"w":"make","s":41.739998,"e":42.14,"sp":0},{"w":"someone","s":42.14,"e":42.62,"sp":0},{"w":"an","s":42.62,"e":43.02,"sp":0},{"w":"enemy.","s":43.02,"e":43.34,"sp":0}],"alts":null},{"i":6,"start":44.345,"end":49.575,"text":"And second, food is one of our last common denominators.","vi":"Và thứ hai, ẩm thực là một trong những điểm chung cuối cùng của chúng ta.","ipa":null,"blanks":[],"words":[{"w":"And","s":44.495,"e":44.735,"sp":0},{"w":"second,","s":44.735,"e":45.535,"sp":0},{"w":"food","s":46.575,"e":46.895,"sp":0},{"w":"is","s":46.895,"e":47.215,"sp":0},{"w":"one","s":47.215,"e":47.375,"sp":0},{"w":"of","s":47.375,"e":47.535,"sp":0},{"w":"our","s":47.535,"e":47.695,"sp":0},{"w":"last","s":47.695,"e":48.015,"sp":0},{"w":"common","s":48.015,"e":48.335,"sp":0},{"w":"denominators.","s":48.335,"e":49.375,"sp":0}],"alts":null},{"i":7,"start":49.705,"end":55.415,"text":"No matter your race, income, or religion, we all have a cuisine,","vi":"Dù bạn thuộc chủng tộc, thu nhập hay tôn giáo nào, tất cả chúng ta đều có một nền ẩm thực,","ipa":null,"blanks":[],"words":[{"w":"No","s":49.855,"e":50.095,"sp":0},{"w":"matter","s":50.095,"e":50.335,"sp":0},{"w":"your","s":50.335,"e":50.655,"sp":0},{"w":"race,","s":50.655,"e":51.295,"sp":0},{"w":"income,","s":51.295,"e":51.934998,"sp":0},{"w":"or","s":51.934998,"e":52.094997,"sp":0},{"w":"religion,","s":52.094997,"e":52.815,"sp":0},{"w":"we","s":53.135,"e":53.375,"sp":0},{"w":"all","s":53.375,"e":53.855,"sp":0},{"w":"have","s":53.855,"e":54.175,"sp":0},{"w":"a","s":54.175,"e":54.415,"sp":0},{"w":"cuisine,","s":54.415,"e":55.214996,"sp":0}],"alts":null},{"i":8,"start":55.545,"end":58.535,"text":"and those cuisines are more than just their ingredients.","vi":"và những nền ẩm thực đó không chỉ đơn thuần là các nguyên liệu.","ipa":null,"blanks":[],"words":[{"w":"and","s":55.695,"e":55.855,"sp":0},{"w":"those","s":55.855,"e":56.095,"sp":0},{"w":"cuisines","s":56.095,"e":56.574997,"sp":0},{"w":"are","s":56.574997,"e":56.815,"sp":0},{"w":"more","s":56.815,"e":57.135,"sp":0},{"w":"than","s":57.135,"e":57.295,"sp":0},{"w":"just","s":57.295,"e":57.535,"sp":0},{"w":"their","s":57.535,"e":57.774998,"sp":0},{"w":"ingredients.","s":57.774998,"e":58.335,"sp":0}],"alts":null},{"i":9,"start":58.87,"end":64.58,"text":"They''re collections of stories, histories, values, memories.","vi":"Chúng là tập hợp của những câu chuyện, lịch sử, giá trị và ký ức.","ipa":null,"blanks":[],"words":[{"w":"They''re","s":59.02,"e":59.420002,"sp":0},{"w":"collections","s":59.420002,"e":59.9,"sp":0},{"w":"of","s":59.9,"e":60.22,"sp":0},{"w":"stories,","s":60.22,"e":61.02,"sp":0},{"w":"histories,","s":61.260002,"e":62.14,"sp":0},{"w":"values,","s":62.38,"e":63.260002,"sp":0},{"w":"memories.","s":63.5,"e":64.38,"sp":0}],"alts":null},{"i":10,"start":65.11,"end":70.98,"text":"When we start to learn something about one another''s cuisine, we often discover something deeper.","vi":"Khi chúng ta bắt đầu tìm hiểu về ẩm thực của nhau, chúng ta thường khám phá ra những điều sâu sắc hơn.","ipa":null,"blanks":[],"words":[{"w":"When","s":65.26,"e":65.58,"sp":0},{"w":"we","s":65.58,"e":65.82,"sp":0},{"w":"start","s":65.82,"e":66.14,"sp":0},{"w":"to","s":66.14,"e":66.3,"sp":0},{"w":"learn","s":66.3,"e":66.7,"sp":0},{"w":"something","s":66.7,"e":67.1,"sp":0},{"w":"about","s":67.1,"e":67.26,"sp":0},{"w":"one","s":67.26,"e":67.5,"sp":0},{"w":"another''s","s":67.5,"e":67.98,"sp":0},{"w":"cuisine,","s":67.98,"e":68.7,"sp":0},{"w":"we","s":68.94,"e":69.1,"sp":0},{"w":"often","s":69.1,"e":69.5,"sp":0},{"w":"discover","s":69.5,"e":70.06,"sp":0},{"w":"something","s":70.06,"e":70.46,"sp":0},{"w":"deeper.","s":70.46,"e":70.78,"sp":0}],"alts":null},{"i":11,"start":71.365,"end":75.235,"text":"We are not as different from each other as we think.","vi":"Chúng ta không khác biệt nhau nhiều như chúng ta vẫn nghĩ.","ipa":null,"blanks":[],"words":[{"w":"We","s":71.515,"e":71.835,"sp":0},{"w":"are","s":71.835,"e":72.075,"sp":0},{"w":"not","s":72.075,"e":72.555,"sp":0},{"w":"as","s":72.555,"e":72.875,"sp":0},{"w":"different","s":72.875,"e":73.274994,"sp":0},{"w":"from","s":73.274994,"e":73.515,"sp":0},{"w":"each","s":73.515,"e":73.755,"sp":0},{"w":"other","s":73.755,"e":73.994995,"sp":0},{"w":"as","s":73.994995,"e":74.314995,"sp":0},{"w":"we","s":74.314995,"e":74.475,"sp":0},{"w":"think.","s":74.475,"e":75.034996,"sp":0}],"alts":null},{"i":12,"start":75.765,"end":81.235,"text":"That''s the bet we made in 2016 with Breaking Bread, Breaking Barriers.","vi":"Đó là cam kết mà chúng tôi đã thực hiện vào năm 2016 với dự án Breaking Bread, Breaking Barriers.","ipa":null,"blanks":[],"words":[{"w":"That''s","s":75.915,"e":76.314995,"sp":0},{"w":"the","s":76.314995,"e":76.555,"sp":0},{"w":"bet","s":76.555,"e":76.795,"sp":0},{"w":"we","s":76.795,"e":76.954994,"sp":0},{"w":"made","s":76.954994,"e":77.274994,"sp":0},{"w":"in","s":77.274994,"e":77.515,"sp":0},{"w":"2016","s":77.515,"e":78.795,"sp":0},{"w":"with","s":78.795,"e":79.115,"sp":0},{"w":"Breaking","s":79.115,"e":79.515,"sp":0},{"w":"Bread,","s":79.515,"e":79.994995,"sp":0},{"w":"Breaking","s":79.994995,"e":80.155,"sp":0},{"w":"Barriers.","s":80.155,"e":81.034996,"sp":0}],"alts":{"6":["two thousand sixteen","twenty sixteen"]}},{"i":13,"start":81.605,"end":90.89,"text":"12 immigrant and native born communities came together in partnership with the Reading Terminal Market, the city, and local organizations.","vi":"12 cộng đồng người nhập cư và người bản địa đã cùng hợp tác với Reading Terminal Market, chính quyền thành phố và các tổ chức địa phương.","ipa":null,"blanks":[],"words":[{"w":"12","s":81.755,"e":82.155,"sp":0},{"w":"immigrant","s":82.155,"e":82.715,"sp":0},{"w":"and","s":82.715,"e":82.955,"sp":0},{"w":"native","s":82.955,"e":83.274994,"sp":0},{"w":"born","s":83.274994,"e":83.595,"sp":0},{"w":"communities","s":83.595,"e":85.115,"sp":0},{"w":"came","s":84.45,"e":84.85,"sp":0},{"w":"together","s":84.85,"e":85.17,"sp":0},{"w":"in","s":85.17,"e":85.409996,"sp":0},{"w":"partnership","s":85.409996,"e":86.13,"sp":0},{"w":"with","s":86.13,"e":86.369995,"sp":0},{"w":"the","s":86.369995,"e":86.53,"sp":0},{"w":"Reading","s":86.53,"e":86.77,"sp":0},{"w":"Terminal","s":86.77,"e":87.17,"sp":0},{"w":"Market,","s":87.17,"e":87.89,"sp":0},{"w":"the","s":88.049995,"e":88.28999,"sp":0},{"w":"city,","s":88.28999,"e":88.93,"sp":0},{"w":"and","s":89.09,"e":89.25,"sp":0},{"w":"local","s":89.25,"e":89.729996,"sp":0},{"w":"organizations.","s":89.729996,"e":90.689995,"sp":0}],"alts":{"0":["twelve"]}},{"i":14,"start":91.26,"end":99.689,"text":"We cooked together, ate together, talked through facilitated dialogue almost entirely about food","vi":"Chúng tôi đã cùng nấu ăn, cùng ăn và trò chuyện thông qua các buổi đối thoại được điều phối, hầu như hoàn toàn về chủ đề ẩm thực","ipa":null,"blanks":[