ds":[{"w":"Chances","s":206.085,"e":206.645,"sp":0},{"w":"are","s":206.645,"e":207.28502,"sp":0},{"w":"they''ll","s":207.52501,"e":207.925,"sp":0},{"w":"start","s":207.925,"e":208.16501,"sp":0},{"w":"telling","s":208.16501,"e":208.40501,"sp":0},{"w":"you","s":208.40501,"e":208.565,"sp":0},{"w":"a","s":208.565,"e":208.80501,"sp":0},{"w":"surprisingly","s":208.80501,"e":209.60501,"sp":0},{"w":"similar","s":209.60501,"e":210.16501,"sp":0},{"w":"story.","s":210.16501,"e":210.88501,"sp":0}],"alts":null},{"i":35,"start":211.295,"end":218.045,"text":"And from there, you''ve just created the possibility that democracy relies upon most,","vi":"Và từ đó, bạn vừa tạo ra khả năng mà nền dân chủ dựa vào nhiều nhất,","ipa":null,"blanks":[],"words":[{"w":"And","s":211.445,"e":211.60501,"sp":0},{"w":"from","s":211.60501,"e":211.925,"sp":0},{"w":"there,","s":211.925,"e":212.48502,"sp":0},{"w":"you''ve","s":212.725,"e":213.205,"sp":0},{"w":"just","s":213.205,"e":213.52501,"sp":0},{"w":"created","s":213.52501,"e":214.005,"sp":0},{"w":"the","s":214.005,"e":214.24501,"sp":0},{"w":"possibility","s":214.24501,"e":215.28502,"sp":0},{"w":"that","s":215.445,"e":215.765,"sp":0},{"w":"democracy","s":215.765,"e":216.565,"sp":0},{"w":"relies","s":216.565,"e":217.125,"sp":0},{"w":"upon","s":217.125,"e":217.52501,"sp":0},{"w":"most,","s":217.52501,"e":217.845,"sp":0}],"alts":null},{"i":36,"start":218.35,"end":223.5,"text":"a connection with those we perceive as different.","vi":"một sự kết nối với những người mà chúng ta coi là khác biệt.","ipa":null,"blanks":[],"words":[{"w":"a","s":218.5,"e":218.9,"sp":0},{"w":"connection","s":218.9,"e":219.7,"sp":0},{"w":"with","s":219.86,"e":220.26,"sp":0},{"w":"those","s":220.26,"e":220.9,"sp":0},{"w":"we","s":220.9,"e":221.3,"sp":0},{"w":"perceive","s":221.3,"e":222.18001,"sp":0},{"w":"as","s":222.26,"e":222.58,"sp":0},{"w":"different.","s":222.58,"e":223.3,"sp":0}],"alts":null},{"i":37,"start":223.79,"end":229.016,"text":"Now let''s get some lunch and build democracy for the next 250 years.","vi":"Bây giờ hãy cùng đi ăn trưa và xây dựng nền dân chủ cho 250 năm tới.","ipa":null,"blanks":[],"words":[{"w":"Now","s":223.94,"e":224.26,"sp":0},{"w":"let''s","s":224.26,"e":224.58,"sp":0},{"w":"get","s":224.58,"e":224.73999,"sp":0},{"w":"some","s":224.73999,"e":224.98,"sp":0},{"w":"lunch","s":224.98,"e":225.37999,"sp":0},{"w":"and","s":225.37999,"e":225.78,"sp":0},{"w":"build","s":225.78,"e":226.26,"sp":0},{"w":"democracy","s":226.26,"e":226.98,"sp":0},{"w":"for","s":226.98,"e":227.22,"sp":0},{"w":"the","s":227.22,"e":227.37999,"sp":0},{"w":"next","s":227.37999,"e":227.54,"sp":0},{"w":"two","s":227.54,"e":227.7,"sp":0},{"w":"hundred","s":227.7,"e":227.86,"sp":0},{"w":"fifty","s":227.86,"e":228.26,"sp":0},{"w":"years.","s":228.26,"e":228.98001,"sp":0}],"alts":{"11":["two hundred fifty"]}},{"i":38,"start":229.024,"end":229.74,"text":"Thank you.","vi":"Cảm ơn các bạn.","ipa":null,"blanks":[],"words":[{"w":"Thank","s":229.06,"e":229.37999,"sp":0},{"w":"you.","s":229.37999,"e":229.54,"sp":0}],"alts":null}]','["dictation","shadowing"]',NULL,NULL,NULL,NULL,NULL,'dictation_shadowing',NULL,NULL,NULL,'tp_society_and_community',NULL,NULL,'2026-10-28T00:00:00.000Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('seed-video-ted-listen-when-you-disagree','video-ted-listen-when-you-disagree','Why It''s So Hard to Listen When You Disagree (TED)',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,1,'Pba4OZjn3cY',NULL,'[{"i":0,"start":4.25,"end":8.12,"text":"You know, there''s something quite strange going on.","vi":"Bạn biết đấy, có một điều gì đó khá kỳ lạ đang diễn ra.","ipa":null,"blanks":[],"words":[{"w":"You","s":4.4,"e":4.72,"sp":0},{"w":"know,","s":4.72,"e":5.04,"sp":0},{"w":"there''s","s":5.04,"e":5.3599997,"sp":0},{"w":"something","s":5.3599997,"e":5.68,"sp":0},{"w":"quite","s":5.68,"e":6.08,"sp":0},{"w":"strange","s":6.08,"e":6.96,"sp":0},{"w":"going","s":6.96,"e":7.3599997,"sp":0},{"w":"on.","s":7.3599997,"e":7.92,"sp":0}],"alts":null},{"i":1,"start":8.25,"end":11.584,"text":"Because most of us believe we should be better listeners,","vi":"Bởi vì hầu hết chúng ta đều tin rằng mình nên là người biết lắng nghe hơn,","ipa":null,"blanks":[],"words":[{"w":"Because","s":8.4,"e":8.72,"sp":0},{"w":"most","s":8.72,"e":9.04,"sp":0},{"w":"of","s":9.04,"e":9.2,"sp":0},{"w":"us","s":9.2,"e":9.36,"sp":0},{"w":"believe","s":9.36,"e":9.679999,"sp":0},{"w":"we","s":9.679999,"e":10,"sp":0},{"w":"should","s":10,"e":10.16,"sp":0},{"w":"be","s":10.16,"e":10.32,"sp":0},{"w":"better","s":10.32,"e":10.639999,"sp":0},{"w":"listeners,","s":10.639999,"e":11.44,"sp":0}],"alts":null},{"i":2,"start":11.616,"end":18.595,"text":"but as I found in my research, we find it so hard, especially when we disagree.","vi":"nhưng như tôi đã phát hiện trong nghiên cứu của mình, chúng ta thấy điều đó rất khó khăn, đặc biệt là khi chúng ta bất đồng quan điểm.","ipa":null,"blanks":[],"words":[{"w":"but","s":11.759999,"e":12.32,"sp":0},{"w":"as","s":12.32,"e":12.639999,"sp":0},{"w":"I","s":12.639999,"e":12.799999,"sp":0},{"w":"found","s":12.799999,"e":13.04,"sp":0},{"w":"in","s":13.04,"e":13.28,"sp":0},{"w":"my","s":13.28,"e":13.5199995,"sp":0},{"w":"research,","s":13.5199995,"e":14.08,"sp":0},{"w":"we","s":14.08,"e":14.24,"sp":0},{"w":"find","s":14.24,"e":14.48,"sp":0},{"w":"it","s":14.48,"e":15.759999,"sp":0},{"w":"so","s":14.715,"e":15.3550005,"sp":0},{"w":"hard,","s":15.3550005,"e":15.995,"sp":0},{"w":"especially","s":16.235,"e":17.035,"sp":0},{"w":"when","s":17.035,"e":17.435,"sp":0},{"w":"we","s":17.435,"e":17.595,"sp":0},{"w":"disagree.","s":17.595,"e":18.395,"sp":0}],"alts":null},{"i":3,"start":18.725,"end":22.619,"text":"There''s a kind of psychological bug that gets in the way.","vi":"Có một loại lỗi tâm lý đang cản trở chúng ta.","ipa":null,"blanks":[],"words":[{"w":"There''s","s":18.875,"e":19.195,"sp":0},{"w":"a","s":19.195,"e":19.275,"sp":0},{"w":"kind","s":19.275,"e":19.515,"sp":0},{"w":"of","s":19.515,"e":19.675,"sp":0},{"w":"psychological","s":19.675,"e":20.475,"sp":0},{"w":"bug","s":20.475,"e":21.195,"sp":0},{"w":"that","s":21.195,"e":21.435,"sp":0},{"w":"gets","s":21.435,"e":21.675,"sp":0},{"w":"in","s":21.675,"e":21.915,"sp":0},{"w":"the","s":21.915,"e":21.994999,"sp":0},{"w":"way.","s":21.994999,"e":22.475,"sp":0}],"alts":null},{"i":4,"start":22.651,"end":29.555,"text":"We fear that if we listen to people whose ideas we find unpalatable, we''ll be contaminated","vi":"Chúng ta sợ rằng nếu lắng nghe những người có ý tưởng mà chúng ta thấy khó chấp nhận, chúng ta sẽ bị ảnh hưởng tiêu cực.","ipa":null,"blanks":[],"words":[{"w":"We","s":22.795,"e":23.035,"sp":0},{"w":"fear","s":23.035,"e":23.355,"sp":0},{"w":"that","s":23.355,"e":23.595001,"sp":0},{"w":"if","s":23.595001,"e":23.835,"sp":0},{"w":"we","s":23.835,"e":23.994999,"sp":0},{"w":"listen","s":23.994999,"e":24.395,"sp":0},{"w":"to","s":24.395,"e":24.555,"sp":0},{"w":"people","s":24.555,"e":24.875,"sp":0},{"w":"whose","s":24.875,"e":25.275,"sp":0},{"w":"ideas","s":25.275,"e":25.915,"sp":0},{"w":"we","s":25.915,"e":26.314999,"sp":0},{"w":"find","s":26.314999,"e":26.555,"sp":0},{"w":"unpalatable,","s":26.555,"e":27.755,"sp":0},{"w":"we''ll","s":27.915,"e":28.075,"sp":0},{"w":"be","s":28.075,"e":28.314999,"sp":0},{"w":"contaminated","s":28.314999,"e":29.355,"sp":0}],"alts":null},{"i":5,"start":29.92,"end":39.05,"text":"Without realizing it, we''ve bought into a dangerous myth. Listening means agreeing. Listening means agreeing.","vi":"Mà không nhận ra, chúng ta đã tin vào một lầm tưởng nguy hiểm. Lắng nghe nghĩa là đồng ý. Lắng nghe nghĩa là đồng ý.","ipa":null,"blanks":[],"words":[{"w":"Without","s":30.07,"e":30.55,"sp":0},{"w":"realizing","s":30.55,"e":31.11,"sp":0},{"w":"it,","s":31.11,"e":31.43,"sp":0},{"w":"we''ve","s":31.43,"e":31.83,"sp":0},{"w":"bought","s":31.83,"e":32.07,"sp":0},{"w":"into","s":32.07,"e":32.47,"sp":0},{"w":"a","s":32.47,"e":32.71,"sp":0},{"w":"dangerous","s":32.71,"e":33.35,"sp":0},{"w":"myth.","s":33.35,"e":34.07,"sp":0},{"w":"Listening","s":34.63,"e":35.43,"sp":0},{"w":"means","s":35.43,"e":36.23,"sp":0},{"w":"agreeing.","s":36.23,"e":36.95,"sp":0},{"w":"Listening","s":37.43,"e":37.91,"sp":0},{"w":"means","s":37.91,"e":38.39,"sp":0},{"w":"agreeing.","s":38.39,"e":39.11,"sp":0}],"alts":null},{"i":6,"start":39.05,"end":46.977,"text":"So we avoid it. And instead, we fixate on trying to explain ourselves more loudly, more fiercely, more insistently.","vi":"Vì vậy, chúng ta tránh né nó. Thay vào đó, chúng ta cố gắng giải thích bản thân một cách to tiếng hơn, quyết liệt hơn và khăng khăng hơn.","ipa":null,"blanks":[],"words":[{"w":"So","s":39.11,"e":39.35,"sp":0},{"w":"we","s":39.35,"e":39.51,"sp":0},{"w":"avoid","s":39.51,"e":39.83,"sp":0},{"w":"it.","s":39.83,"e":40.309998,"sp":0},{"w":"And","s":40.55,"e":40.71,"sp":0},{"w":"instead,","s":40.71,"e":41.19,"sp":0},{"w":"we","s":41.19,"e":41.35,"sp":0},{"w":"fixate","s":41.35,"e":41.83,"sp":0},{"w":"on","s":41.83,"e":42.07,"sp":0},{"w":"trying","s":42.07,"e":42.309998,"sp":0},{"w":"to","s":42.309998,"e":42.39,"sp":0},{"w":"explain","s":42.39,"e":42.87,"sp":0},{"w":"ourselves","s":42.87,"e":44.47,"sp":0},{"w":"more","s":43.704998,"e":44.024998,"sp":0},{"w":"loudly,","s":44.024998,"e":44.664997,"sp":0},{"w":"more","s":44.664997,"e":44.905,"sp":0},{"w":"fiercely,","s":44.905,"e":45.625,"sp":0},{"w":"more","s":45.625,"e":45.864998,"sp":0},{"w":"insistently.","s":45.864998,"e":46.905,"sp":0}],"alts":null},{"i":7,"start":46.993,"end":49.265,"text":"If only they''d understand.","vi":"Giá mà họ hiểu cho.","ipa":null,"blanks":[],"words":[{"w":"If","s":47.065,"e":47.385,"sp":0},{"w":"only","s":47.385,"e":47.784996,"sp":0},{"w":"they''d","s":47.784996,"e":48.265,"sp":0},{"w":"understand.","s":48.265,"e":49.065,"sp":0}],"alts":null},{"i":8,"start":49.955,"end":52.257,"text":"You know, I should know,","vi":"Bạn biết đấy, tôi đáng lẽ phải biết điều đó,","ipa":null,"blanks":[],"words":[{"w":"You","s":50.105,"e":50.344997,"sp":0},{"w":"know,","s":50.344997,"e":50.745,"sp":0},{"w":"I","s":50.745,"e":51.304996,"sp":0},{"w":"should","s":51.304996,"e":51.625,"sp":0},{"w":"know,","s":51.625,"e":52.184998,"sp":0}],"alts":null},{"i":9,"start":52.273,"end":61.76,"text":"because I threw away a once in a lifetime opportunity to understand one of Africa''s most most intriguing and powerful leaders because","vi":"bởi vì tôi đã bỏ lỡ một cơ hội ngàn năm có một để hiểu về một trong những nhà lãnh đạo quyền lực và thú vị nhất châu Phi vì","ipa":null,"blanks":[],"words":[{"w":"because","s":52.344997,"e":52.585,"sp":0},{"w":"I","s":52.585,"e":52.905,"sp":0},{"w":"threw","s":52.905,"e":53.144997,"sp":0},{"w":"away","s":53.144997,"e":53.545,"sp":0},{"w":"a","s":53.545,"e":53.864998,"sp":0},{"w":"once","s":53.864998,"e":54.184998,"sp":0},{"w":"in","s":54.184998,"e":54.425,"sp":0},{"w":"a","s":54.425,"e":54.585,"sp":0},{"w":"lifetime","s":54.585,"e":55.065,"sp":0},{"w":"opportunity","s":55.065,"e":55.945,"sp":0},{"w":"to","s":55.945,"e":56.265,"sp":0},{"w":"understand","s":56.265,"e":56.664997,"sp":0},{"w":"one","s":56.664997,"e":56.905,"sp":0},{"w":"of","s":56.905,"e":56.984997,"sp":0},{"w":"Africa''s","s":56.984997,"e":57.784996,"sp":0},{"w":"most","s":57.784996,"e":58.265,"sp":0},{"w":"most","s":58.38,"e":58.86,"sp":0},{"w":"intriguing","s":58.86,"e":59.420002,"sp":0},{"w":"and","s":59.420002,"e":59.74,"sp":0},{"w":"powerful","s":59.74,"e":60.22,"sp":0},{"w":"leaders","s":60.22,"e":60.86,"sp":0},{"w":"because","s":60.86,"e":61.58,"sp":0}],"alts":null},{"i":10,"start":61.83,"end":63.78,"text":"I wasn''t ready to listen.","vi":"tôi đã không sẵn sàng để lắng nghe.","ipa":null,"blanks":[],"words":[{"w":"I","s":61.98,"e":62.22,"sp":0},{"w":"wasn''t","s":62.22,"e":62.54,"sp":0},{"w":"ready","s":62.54,"e":62.86,"sp":0},{"w":"to","s":62.86,"e":63.02,"sp":0},{"w":"listen.","s":63.02,"e":63.58,"sp":0}],"alts":null},{"i":11,"start":64.23,"end":70.18,"text":"So let me tell you about a time when I was in Ethiopia reporting for the BBC at the start of my career.","vi":"Vậy hãy để tôi kể cho bạn nghe về một lần tôi ở Ethiopia làm phóng viên cho BBC khi mới bắt đầu sự nghiệp.","ipa":null,"blanks":[],"words":[{"w":"So","s":64.380005,"e":64.62,"sp":0},{"w":"let","s":64.62,"e":64.86,"sp":0},{"w":"me","s":64.86,"e":64.94,"sp":0},{"w":"tell","s":64.94,"e":65.1,"sp":0},{"w":"you","s":65.1,"e":65.26,"sp":0},{"w":"about","s":65.26,"e":65.42,"sp":0},{"w":"a","s":65.42,"e":65.58,"sp":0},{"w":"time","s":65.58,"e":65.82,"sp":0},{"w":"when","s":65.82,"e":66.06,"sp":0},{"w":"I","s":66.06,"e":66.22,"sp":0},{"w":"was","s":66.22,"e":66.380005,"sp":0},{"w":"in","s":66.380005,"e":66.62,"sp":0},{"w":"Ethiopia","s":66.62,"e":67.42,"sp":0},{"w":"reporting","s":67.42,"e":67.98,"sp":0},{"w":"for","s":67.98,"e":68.14,"sp":0},{"w":"the","s":68.14,"e":68.22,"sp":0},{"w":"BBC","s":68.22,"e":68.7,"sp":0},{"w":"at","s":68.7,"e":68.94,"sp":0},{"w":"the","s":68.94,"e":69.1,"sp":0},{"w":"start","s":69.1,"e":69.26,"sp":0},{"w":"of","s":69.26,"e":69.42,"sp":0},{"w":"my","s":69.42,"e":69.66,"sp":0},{"w":"career.","s":69.66,"e":69.98,"sp":0}],"alts":null},{"i":12,"start":70.555,"end":76.181,"text":"I''d landed an interview with its president and later prime minister, Meles Zanawi.","vi":"Tôi đã có được một cuộc phỏng vấn với tổng thống và sau đó là thủ tướng, Meles Zanawi.","ipa":null,"blanks":[],"words":[{"w":"I''d","s":70.705,"e":71.185,"sp":0},{"w":"landed","s":71.185,"e":71.665,"sp":0},{"w":"an","s":71.665,"e":71.905,"sp":0},{"w":"interview","s":71.905,"e":72.305,"sp":0},{"w":"with","s":72.305,"e":72.465,"sp":0},{"w":"its","s":72.465,"e":72.705,"sp":0},{"w":"president","s":72.705,"e":73.104996,"sp":0},{"w":"and","s":73.104996,"e":73.424995,"sp":0},{"w":"later","s":73.424995,"e":73.665,"sp":0},{"w":"prime","s":73.665,"e":74.064995,"sp":0},{"w":"minister,","s":74.064995,"e":74.625,"sp":0},{"w":"Meles","s":74.625,"e":75.025,"sp":0},{"w":"Zanawi.","s":75.025,"e":76.145,"sp":0}],"alts":null},{"i":13,"start":76.189,"end":80.209,"text":"I was so proud. This was my big scoop.","vi":"Tôi đã rất tự hào. Đây là tin độc quyền lớn của tôi.","ipa":null,"blanks":[],"words":[{"w":"I","s":76.225,"e":76.384995,"sp":0},{"w":"was","s":76.384995,"e":76.625,"sp":0},{"w":"so","s":76.625,"e":77.025,"sp":0},{"w":"proud.","s":77.025,"e":77.585,"sp":0},{"w":"This","s":77.585,"e":77.744995,"sp":0},{"w":"was","s":77.744995,"e":78.225,"sp":0},{"w":"my","s":78.225,"e":78.865,"sp":0},{"w":"big","s":78.865,"e":79.265,"sp":0},{"w":"scoop.","s":79.265,"e":80.064995,"sp":0}],"alts":null},{"i":14,"start":80.241,"end":84.105,"text":"But it was also a time when his opponents were tortured or disappeared.","vi":"Nhưng đó cũng là thời điểm mà những người phản đối ông bị tra tấn hoặc mất tích.","ipa":null,"blanks":[],"words":[{"w":"But","s":80.384995,"e":80.545,"sp":0},{"w":"it","s":80.545,"e":80.705,"sp":0},{"w":"was","s":80.705,"e":80.865,"sp":0},{"w":"also","s":80.865,"e":81.104996,"sp":0},{"w":"a","s":81.104996,"e":81.345,"sp":0},{"w":"time","s":81.345,"e":81.505,"sp":0},{"w":"when","s":81.505,"e":81.744995,"sp":0},{"w":"his","s":81.744995,"e":81.985,"sp":0},{"w":"opponents","s":81.985,"e":82.384995,"sp":0},{"w":"were","s":82.384995,"e":82.705,"sp":0},{"w":"tortured","s":82.705,"e":83.185,"sp":0},{"w":"or","s":83.185,"e":83.424995,"sp":0},{"w":"disappeared.","s":83.424995,"e":83.905,"sp":0}],"alts":null},{"i":15,"start":84.42,"end":90.11,"text":"So the president, he was keen to talk about his record crop production of maize,","vi":"Vì vậy, vị tổng thống, ông ấy rất muốn nói về thành tích sản xuất ngô kỷ lục của mình,","ipa":null,"blanks":[],"words":[{"w":"So","s":84.57,"e":84.89,"sp":0},{"w":"the","s":84.89,"e":85.05,"sp":0},{"w":"president,","s":85.05,"e":85.69,"sp":0},{"w":"he","s":85.69,"e":85.93,"sp":0},{"w":"was","s":85.93,"e":86.09,"sp":0},{"w":"keen","s":86.09,"e":86.49,"sp":0},{"w":"to","s":86.49,"e":86.65,"sp":0},{"w":"talk","s":86.65,"e":86.97,"sp":0},{"w":"about","s":86.97,"e":87.21,"sp":0},{"w":"his","s":87.21,"e":87.37,"sp":0},{"w":"record","s":87.37,"e":87.77,"sp":0},{"w":"crop","s":87.77,"e":88.409996,"sp":0},{"w":"production","s":88.57,"e":89.05,"sp":0},{"w":"of","s":89.05,"e":89.61,"sp":0},{"w":"maize,","s":89.61,"e":90.17,"sp":0}],"alts":null},{"i":16,"start":90.11,"end":94.634,"text":"of sorghum and barley, critical in a country with a history of famine.","vi":"của cao lương và lúa mạch, những thứ rất quan trọng ở một quốc gia có lịch sử nạn đói.","ipa":null,"blanks":[],"words":[{"w":"of","s":90.17,"e":90.33,"sp":0},{"w":"sorghum","s":90.33,"e":90.729996,"sp":0},{"w":"and","s":90.729996,"e":90.97,"sp":0},{"w":"barley,","s":90.97,"e":91.69,"sp":0},{"w":"critical","s":91.69,"e":92.09,"sp":0},{"w":"in","s":92.09,"e":92.25,"sp":0},{"w":"a","s":92.25,"e":92.409996,"sp":0},{"w":"country","s":92.409996,"e":92.81,"sp":0},{"w":"with","s":92.81,"e":93.13,"sp":0},{"w":"a","s":93.13,"e":93.29,"sp":0},{"w":"history","s":93.29,"e":93.53,"sp":0},{"w":"of","s":93.53,"e":93.69,"sp":0},{"w":"famine.","s":93.69,"e":94.49,"sp":0}],"alts":null},{"i":17,"start":94.666,"end":100.05,"text":"But I refused to listen, incessantly circling back to human rights.","vi":"Nhưng tôi từ chối lắng nghe, liên tục quay lại chủ đề nhân quyền.","ipa":null,"blanks":[],"words":[{"w":"But","s":94.81,"e":94.97,"sp":0},{"w":"I","s":94.97,"e":95.53,"sp":0},{"w":"refused","s":95.53,"e":96.09,"sp":0},{"w":"to","s":96.09,"e":96.25,"sp":0},{"w":"listen,","s":96.25,"e":96.89,"sp":0},{"w":"incessantly","s":96.97,"e":98.01,"sp":0},{"w":"circling","s":98.01,"e":98.49,"sp":0},{"w":"back","s":98.49,"e":98.97,"sp":0},{"w":"to","s":98.97,"e":99.21,"sp":0},{"w":"human","s":99.21,"e":99.53,"sp":0},{"w":"rights.","s":99.53,"e":99.85,"sp":0}],"alts":null},{"i":18,"start":100.385,"end":106.335,"text":"To be honest, my questions, they were masks for my desire to confront the president.","vi":"Thành thật mà nói, các câu hỏi của tôi chỉ là cái cớ cho mong muốn đối đầu với tổng thống.","ipa":null,"blanks":[],"words":[{"w":"To","s":100.535,"e":100.775,"sp":0},{"w":"be","s":100.775,"e":100.935005,"sp":0},{"w":"honest,","s":100.935005,"e":101.335,"sp":0},{"w":"my","s":101.335,"e":101.575005,"sp":0},{"w":"questions,","s":101.575005,"e":102.215004,"sp":0},{"w":"they","s":102.215004,"e":102.375,"sp":0},{"w":"were","s":102.375,"e":102.615005,"sp":0},{"w":"masks","s":102.615005,"e":103.095,"sp":0},{"w":"for","s":103.095,"e":103.335,"sp":0},{"w":"my","s":103.335,"e":103.575005,"sp":0},{"w":"desire","s":103.575005,"e":104.055,"sp":0},{"w":"to","s":104.055,"e":104.375,"sp":0},{"w":"confront","s":104.375,"e":105.095,"sp":0},{"w":"the","s":105.095,"e":105.415,"sp":0},{"w":"president.","s":105.415,"e":106.135,"sp":0}],"alts":null},{"i":19,"start":106.465,"end":107.675,"text":"And what did he do?","v