8.08,"sp":0},{"w":"that","s":118.08,"e":118.4,"sp":0},{"w":"I","s":118.4,"e":118.56,"sp":0},{"w":"was","s":118.56,"e":118.72,"sp":0},{"w":"wrong","s":118.72,"e":119.04,"sp":0},{"w":"to","s":119.04,"e":119.28,"sp":0},{"w":"hold","s":119.28,"e":119.520004,"sp":0},{"w":"the","s":119.520004,"e":119.68,"sp":0},{"w":"president","s":119.68,"e":120,"sp":0},{"w":"to","s":120,"e":120.32,"sp":0},{"w":"account,","s":120.32,"e":120.96,"sp":0},{"w":"that","s":121.12,"e":121.28,"sp":0},{"w":"was","s":121.28,"e":121.520004,"sp":0},{"w":"essential,","s":121.520004,"e":122.24,"sp":0}],"alts":null},{"i":22,"start":122.416,"end":129.068,"text":"but my lack of curiosity and my inability to listen caused him to put up his defenses,","vi":"nhưng sự thiếu tò mò và khả năng lắng nghe kém của tôi đã khiến ông ấy phải phòng thủ,","ipa":null,"blanks":[],"words":[{"w":"but","s":122.56,"e":122.72,"sp":0},{"w":"my","s":122.72,"e":122.96,"sp":0},{"w":"lack","s":122.96,"e":123.200005,"sp":0},{"w":"of","s":123.200005,"e":123.44,"sp":0},{"w":"curiosity","s":123.44,"e":124.32,"sp":0},{"w":"and","s":124.32,"e":124.64,"sp":0},{"w":"my","s":124.64,"e":124.880005,"sp":0},{"w":"inability","s":124.880005,"e":125.36,"sp":0},{"w":"to","s":125.36,"e":125.68,"sp":0},{"w":"listen","s":125.68,"e":126.32,"sp":0},{"w":"caused","s":126.32,"e":126.8,"sp":0},{"w":"him","s":126.8,"e":127.200005,"sp":0},{"w":"to","s":127.200005,"e":127.520004,"sp":0},{"w":"put","s":127.520004,"e":127.68,"sp":0},{"w":"up","s":127.68,"e":127.840004,"sp":0},{"w":"his","s":127.840004,"e":128.08,"sp":0},{"w":"defenses,","s":128.08,"e":128.96,"sp":0}],"alts":null},{"i":23,"start":129.092,"end":132.895,"text":"and so I walked away empty handed.","vi":"và thế là tôi ra về tay trắng.","ipa":null,"blanks":[],"words":[{"w":"and","s":129.2,"e":129.36,"sp":0},{"w":"so","s":129.36,"e":129.6,"sp":0},{"w":"I","s":129.6,"e":130.24,"sp":0},{"w":"walked","s":130.24,"e":130.64,"sp":0},{"w":"away","s":130.64,"e":131.2,"sp":0},{"w":"empty","s":131.575,"e":131.97499,"sp":0},{"w":"handed.","s":131.97499,"e":132.695,"sp":0}],"alts":null},{"i":24,"start":133.025,"end":139.247,"text":"And over the years, I''ve learned from my mistakes as a journalist and my work as an executive coach,","vi":"Và qua nhiều năm, tôi đã học hỏi từ những sai lầm của mình với tư cách là một nhà báo và công việc huấn luyện điều hành,","ipa":null,"blanks":[],"words":[{"w":"And","s":133.17499,"e":133.33499,"sp":0},{"w":"over","s":133.33499,"e":133.575,"sp":0},{"w":"the","s":133.575,"e":133.655,"sp":0},{"w":"years,","s":133.655,"e":133.97499,"sp":0},{"w":"I''ve","s":133.97499,"e":134.135,"sp":0},{"w":"learned","s":134.135,"e":134.375,"sp":0},{"w":"from","s":134.375,"e":134.61499,"sp":0},{"w":"my","s":134.61499,"e":135.015,"sp":0},{"w":"mistakes","s":135.015,"e":135.81499,"sp":0},{"w":"as","s":135.81499,"e":136.135,"sp":0},{"w":"a","s":136.135,"e":136.215,"sp":0},{"w":"journalist","s":136.215,"e":136.855,"sp":0},{"w":"and","s":136.855,"e":137.17499,"sp":0},{"w":"my","s":137.17499,"e":137.33499,"sp":0},{"w":"work","s":137.33499,"e":137.655,"sp":0},{"w":"as","s":137.655,"e":137.89499,"sp":0},{"w":"an","s":137.89499,"e":138.055,"sp":0},{"w":"executive","s":138.055,"e":138.61499,"sp":0},{"w":"coach,","s":138.61499,"e":139.175,"sp":0}],"alts":null},{"i":25,"start":139.263,"end":143.211,"text":"and I''ve drawn on scholars, on psychologists and peace builders,","vi":"và tôi đã dựa vào các học giả, các nhà tâm lý học và những người xây dựng hòa bình,","ipa":null,"blanks":[],"words":[{"w":"and","s":139.33499,"e":139.415,"sp":0},{"w":"I''ve","s":139.415,"e":139.655,"sp":0},{"w":"drawn","s":139.655,"e":139.89499,"sp":0},{"w":"on","s":139.89499,"e":140.135,"sp":0},{"w":"scholars,","s":140.135,"e":140.935,"sp":0},{"w":"on","s":140.935,"e":141.25499,"sp":0},{"w":"psychologists","s":141.25499,"e":141.89499,"sp":0},{"w":"and","s":141.89499,"e":142.215,"sp":0},{"w":"peace","s":142.215,"e":142.45499,"sp":0},{"w":"builders,","s":142.45499,"e":143.175,"sp":0}],"alts":null},{"i":26,"start":143.219,"end":150.59,"text":"and I''ve woven these ideas together into a book and an approach I call deep listening.","vi":"và tôi đã đúc kết những ý tưởng này thành một cuốn sách và một phương pháp mà tôi gọi là lắng nghe sâu.","ipa":null,"blanks":[],"words":[{"w":"and","s":143.25499,"e":143.415,"sp":0},{"w":"I''ve","s":143.415,"e":143.655,"sp":0},{"w":"woven","s":143.655,"e":143.97499,"sp":0},{"w":"these","s":143.97499,"e":144.215,"sp":0},{"w":"ideas","s":144.215,"e":144.69499,"sp":0},{"w":"together","s":144.69499,"e":145.415,"sp":0},{"w":"into","s":145.575,"e":145.97499,"sp":0},{"w":"a","s":145.97499,"e":146.135,"sp":0},{"w":"book","s":146.135,"e":146.775,"sp":0},{"w":"and","s":146.97,"e":147.29001,"sp":0},{"w":"an","s":147.29001,"e":147.53,"sp":0},{"w":"approach","s":147.53,"e":148.01,"sp":0},{"w":"I","s":148.01,"e":148.41,"sp":0},{"w":"call","s":148.41,"e":148.97,"sp":0},{"w":"deep","s":148.97,"e":149.61,"sp":0},{"w":"listening.","s":149.61,"e":150.41,"sp":0}],"alts":null},{"i":27,"start":150.66,"end":158.714,"text":"Because the standard way we so often perform listening, it starves us of real connections.","vi":"Bởi vì cách thông thường mà chúng ta hay thực hiện việc lắng nghe, nó làm chúng ta mất đi những kết nối thực sự.","ipa":null,"blanks":[],"words":[{"w":"Because","s":150.81,"e":151.05,"sp":0},{"w":"the","s":151.05,"e":151.37,"sp":0},{"w":"standard","s":151.37,"e":151.77,"sp":0},{"w":"way","s":151.77,"e":152.09,"sp":0},{"w":"we","s":152.09,"e":152.25,"sp":0},{"w":"so","s":152.25,"e":152.49,"sp":0},{"w":"often","s":152.49,"e":153.13,"sp":0},{"w":"perform","s":153.21,"e":154.25002,"sp":0},{"w":"listening,","s":154.33,"e":155.05,"sp":0},{"w":"it","s":155.77,"e":156.01,"sp":0},{"w":"starves","s":156.01,"e":156.41,"sp":0},{"w":"us","s":156.41,"e":156.97,"sp":0},{"w":"of","s":157.13,"e":157.37,"sp":0},{"w":"real","s":157.37,"e":157.77,"sp":0},{"w":"connections.","s":157.77,"e":158.57,"sp":0}],"alts":null},{"i":28,"start":158.746,"end":165.835,"text":"We struggle to engage with our coworkers, with our family. Just ask my own.","vi":"Chúng ta chật vật để kết nối với đồng nghiệp, với gia đình. Cứ hỏi người nhà tôi mà xem.","ipa":null,"blanks":[],"words":[{"w":"We","s":158.89,"e":159.13,"sp":0},{"w":"struggle","s":159.13,"e":159.61,"sp":0},{"w":"to","s":159.61,"e":159.85,"sp":0},{"w":"engage","s":159.85,"e":160.33,"sp":0},{"w":"with","s":160.33,"e":160.65,"sp":0},{"w":"our","s":160.65,"e":161.05,"sp":0},{"w":"coworkers,","s":161.05,"e":161.77,"sp":0},{"w":"with","s":162.43501,"e":162.755,"sp":0},{"w":"our","s":162.755,"e":162.99501,"sp":0},{"w":"family.","s":162.99501,"e":163.79501,"sp":0},{"w":"Just","s":164.115,"e":164.43501,"sp":0},{"w":"ask","s":164.43501,"e":164.835,"sp":0},{"w":"my","s":164.835,"e":165.15501,"sp":0},{"w":"own.","s":165.15501,"e":165.63501,"sp":0}],"alts":null},{"i":29,"start":166.205,"end":172.075,"text":"Anyone from a different background or generation, anyone whose ideas conflict with our own.","vi":"Bất kỳ ai từ một nền tảng hoặc thế hệ khác, bất kỳ ai có ý tưởng xung đột với chúng ta.","ipa":null,"blanks":[],"words":[{"w":"Anyone","s":166.35501,"e":166.835,"sp":0},{"w":"from","s":166.835,"e":167.15501,"sp":0},{"w":"a","s":167.15501,"e":167.315,"sp":0},{"w":"different","s":167.315,"e":167.63501,"sp":0},{"w":"background","s":167.63501,"e":168.115,"sp":0},{"w":"or","s":168.115,"e":168.35501,"sp":0},{"w":"generation,","s":168.35501,"e":169.15501,"sp":0},{"w":"anyone","s":169.235,"e":169.475,"sp":0},{"w":"whose","s":169.475,"e":169.79501,"sp":0},{"w":"ideas","s":169.79501,"e":170.35501,"sp":0},{"w":"conflict","s":170.35501,"e":170.91501,"sp":0},{"w":"with","s":170.91501,"e":171.235,"sp":0},{"w":"our","s":171.235,"e":171.395,"sp":0},{"w":"own.","s":171.395,"e":171.87502,"sp":0}],"alts":null},{"i":30,"start":172.365,"end":178.4,"text":"Now, you see, I think I''m rational, and my sense is that you think you''re rational,","vi":"Bây giờ, bạn thấy đấy, tôi nghĩ mình là người lý trí, và tôi cảm thấy bạn cũng nghĩ mình là người lý trí,","ipa":null,"blanks":[],"words":[{"w":"Now,","s":172.51501,"e":172.835,"sp":0},{"w":"you","s":172.835,"e":172.99501,"sp":0},{"w":"see,","s":172.99501,"e":173.475,"sp":0},{"w":"I","s":173.475,"e":173.79501,"sp":0},{"w":"think","s":173.79501,"e":174.035,"sp":0},{"w":"I''m","s":174.035,"e":174.35501,"sp":0},{"w":"rational,","s":174.35501,"e":174.755,"sp":0},{"w":"and","s":175.34001,"e":175.58,"sp":0},{"w":"my","s":175.58,"e":175.90001,"sp":0},{"w":"sense","s":175.90001,"e":176.14,"sp":0},{"w":"is","s":176.14,"e":176.38,"sp":0},{"w":"that","s":176.38,"e":176.7,"sp":0},{"w":"you","s":176.7,"e":176.94,"sp":0},{"w":"think","s":176.94,"e":177.18001,"sp":0},{"w":"you''re","s":177.18001,"e":177.58,"sp":0},{"w":"rational,","s":177.58,"e":178.22002,"sp":0}],"alts":null},{"i":31,"start":178.47,"end":186.02,"text":"but we''re all driven by our judgments, by our emotions and our past, clinging onto the moral high ground.","vi":"nhưng tất cả chúng ta đều bị dẫn dắt bởi những phán xét, cảm xúc và quá khứ, bám víu vào vị thế đạo đức cao thượng.","ipa":null,"blanks":[],"words":[{"w":"but","s":178.62001,"e":178.78,"sp":0},{"w":"we''re","s":178.78,"e":179.1,"sp":0},{"w":"all","s":179.1,"e":179.18001,"sp":0},{"w":"driven","s":179.18001,"e":179.90001,"sp":0},{"w":"by","s":179.90001,"e":180.46,"sp":0},{"w":"our","s":180.46,"e":180.86,"sp":0},{"w":"judgments,","s":180.86,"e":181.66,"sp":0},{"w":"by","s":181.66,"e":181.82,"sp":0},{"w":"our","s":181.82,"e":181.98001,"sp":0},{"w":"emotions","s":181.98001,"e":182.46,"sp":0},{"w":"and","s":182.46,"e":182.7,"sp":0},{"w":"our","s":182.7,"e":182.94,"sp":0},{"w":"past,","s":182.94,"e":183.66,"sp":0},{"w":"clinging","s":183.98001,"e":184.38,"sp":0},{"w":"onto","s":184.38,"e":184.7,"sp":0},{"w":"the","s":184.7,"e":184.86,"sp":0},{"w":"moral","s":184.86,"e":185.26001,"sp":0},{"w":"high","s":185.26001,"e":185.58,"sp":0},{"w":"ground.","s":185.58,"e":185.82,"sp":0}],"alts":null},{"i":32,"start":187.045,"end":193.395,"text":"The problem is that from an early age, we''ve been brought up to believe that listening means agreement,","vi":"Vấn đề là từ khi còn nhỏ, chúng ta đã được dạy rằng lắng nghe nghĩa là đồng ý,","ipa":null,"blanks":[],"words":[{"w":"The","s":187.195,"e":187.435,"sp":0},{"w":"problem","s":187.435,"e":187.755,"sp":0},{"w":"is","s":187.755,"e":187.99501,"sp":0},{"w":"that","s":187.99501,"e":188.235,"sp":0},{"w":"from","s":188.235,"e":188.475,"sp":0},{"w":"an","s":188.475,"e":188.63501,"sp":0},{"w":"early","s":188.63501,"e":188.875,"sp":0},{"w":"age,","s":188.875,"e":189.27501,"sp":0},{"w":"we''ve","s":189.27501,"e":189.515,"sp":0},{"w":"been","s":189.515,"e":189.595,"sp":0},{"w":"brought","s":189.595,"e":189.835,"sp":0},{"w":"up","s":189.835,"e":190.075,"sp":0},{"w":"to","s":190.075,"e":190.235,"sp":0},{"w":"believe","s":190.235,"e":190.63501,"sp":0},{"w":"that","s":190.63501,"e":191.115,"sp":0},{"w":"listening","s":191.115,"e":191.755,"sp":0},{"w":"means","s":191.755,"e":192.315,"sp":0},{"w":"agreement,","s":192.315,"e":193.195,"sp":0}],"alts":null},{"i":33,"start":193.765,"end":196.459,"text":"that listening signals obedience.","vi":"rằng lắng nghe là tín hiệu của sự phục tùng.","ipa":null,"blanks":[],"words":[{"w":"that","s":193.91501,"e":194.235,"sp":0},{"w":"listening","s":194.235,"e":194.715,"sp":0},{"w":"signals","s":194.715,"e":195.35501,"sp":0},{"w":"obedience.","s":195.35501,"e":196.31502,"sp":0}],"alts":null},{"i":34,"start":196.491,"end":200.217,"text":"You know, I remember my first teacher yelling at me, Listen to me.","vi":"Bạn biết đấy, tôi nhớ giáo viên đầu tiên của mình đã quát tôi: \"Nghe tôi nói này.\"","ipa":null,"blanks":[],"words":[{"w":"You","s":196.63501,"e":196.715,"sp":0},{"w":"know,","s":196.715,"e":196.955,"sp":0},{"w":"I","s":196.955,"e":197.035,"sp":0},{"w":"remember","s":197.035,"e":197.35501,"sp":0},{"w":"my","s":197.35501,"e":197.595,"sp":0},{"w":"first","s":197.595,"e":197.835,"sp":0},{"w":"teacher","s":197.835,"e":198.155,"sp":0},{"w":"yelling","s":198.155,"e":198.63501,"sp":0},{"w":"at","s":198.63501,"e":198.795,"sp":0},{"w":"me,","s":198.795,"e":199.115,"sp":0},{"w":"Listen","s":199.115,"e":199.675,"sp":0},{"w":"to","s":199.675,"e":199.835,"sp":0},{"w":"me.","s":199.835,"e":200.075,"sp":0}],"alts":null},{"i":35,"start":200.248,"end":204.818,"text":"What she meant is, Obey me, keep quiet, put those crayons away.","vi":"Ý bà ấy là: \"Vâng lời tôi, giữ trật tự, cất bút màu đi.\"","ipa":null,"blanks":[],"words":[{"w":"What","s":200.39,"e":200.87,"sp":0},{"w":"she","s":200.87,"e":201.03,"sp":0},{"w":"meant","s":201.03,"e":201.27,"sp":0},{"w":"is,","s":201.27,"e":201.75,"sp":0},{"w":"Obey","s":201.75,"e":202.15,"sp":0},{"w":"me,","s":202.15,"e":202.55,"sp":0},{"w":"keep","s":202.55,"e":202.79,"sp":0},{"w":"quiet,","s":202.79,"e":203.27,"sp":0},{"w":"put","s":203.27,"e":203.43,"sp":0},{"w":"those","s":203.43,"e":203.59,"sp":0},{"w":"crayons","s":203.59,"e":204.15,"sp":0},{"w":"away.","s":204.15,"e":204.71,"sp":0}],"alts":null},{"i":36,"start":204.842,"end":209.23,"text":"It wasn''t really an invitation to listen. It was a command to comply.","vi":"Đó không thực sự là một lời mời lắng nghe. Đó là một mệnh lệnh phải tuân theo.","ipa":null,"blanks":[],"words":[{"w":"It","s":204.95,"e":205.11,"sp":0},{"w":"wasn''t","s":205.11,"e":205.34999,"sp":0},{"w":"really","s":205.34999,"e":205.59,"sp":0},{"w":"an","s":205.59,"e":205.75,"sp":0},{"w":"invitation","s":205.75,"e":206.23,"sp":0},{"w":"to","s":206.23,"e":206.39,"sp":0},{"w":"listen.","s":206.39,"e":206.95001,"sp":0},{"w":"It","s":207.11,"e":207.27,"sp":0},{"w":"was","s":207.27,"e":207.43,"sp":0},{"w":"a","s":207.43,"e":207.59,"sp":0},{"w":"command","s":207.59,"e":207.98999,"sp":0},{"w":"to","s":207.98999,"e":208.31,"sp":0},{"w":"comply.","s":208.31,"e":209.03,"sp":0}],"alts":null},{"i":37,"start":209.44,"end":213.558,"text":"And this muddling up of listening and agreement means that now as adults,","vi":"Và sự nhầm lẫn giữa lắng nghe và đồng ý này có nghĩa là bây giờ khi đã trưởng thành,","ipa":null,"blanks":[],"words":[{"w":"And","s":209.59,"e":209.75,"sp":0},{"w":"this","s":209.75,"e":209.91,"sp":0},{"w":"muddling","s":209.91,"e":210.47,"sp":0},{"w":"up","s":210.47,"e":210.70999,"sp":0},{"w":"of","s":210.70999,"e":210.95,"sp":0},{"w":"listening","s":210.95,"e":211.27,"sp":0},{"w":"and","s":211.27,"e":211.51,"sp":0},{"w":"agreement","s":211.51,"e":212.06999,"sp":0},{"w":"means","s":212.06999,"e":212.39,"sp":0},{"w":"that","s":212.39,"e":212.55,"sp":0},{"w":"now","s":212.55,"e":212.79,"sp":0},{"w":"as","s":212.79,"e":213.03,"sp":0},{"w":"adults,","s":213.03,"e":213.43,"sp":0}],"alts":null},{"i":38,"start":213.587,"end":218.075,"text":"we fear listening to people whose ideas might disturb us.","vi":"chúng ta sợ lắng nghe những người có ý tưởng có thể làm chúng ta khó chịu.","ipa":null,"blanks":[],"words":[{"w":"we","s":213.715,"e":214.03499,"sp":0},{"w":"fear","s":214.03499,"e":214.355,"sp":0},{"w":"listening","s":214.355,"e":214.75499,"sp":0},{"w":"to","s":214.75499,"e":214.915,"sp":0},{"w":"people","s":214.915,"e":215.31499,"sp":0},{"w":"whose","s":215.31499,"e":215.715,"sp":0},{"w":"ideas","s":215.715,"e":216.275,"sp":0},{"w":"might","s":216.275,"e":216.75499,"sp":0},{"w":"disturb","s":216.75499,"e":217.31499,"sp":0},{"w":"us.","s":217.31499,"e":217.875,"sp":0}],"alts":null},{"i":39,"start":218.765,"end":220.635,"text":"Will I lose myself?","vi":"Liệu tôi có đánh mất chính mình không?","ipa":null,"blanks":[],"words":[{"w":"Will","s":218.915,"e":219.23499,"sp":0},{"w":"I","s":219.23499,"e":219.39499,"sp":0},{"w":"lose","s":219.39499,"e":219.635,"sp":0},{"w":"myself?","s":219.635,"e":220.435,"sp":0}],"alts":null},{"i":40,"start":221.565,"end":224.155,"text":"Will I be forced to change my mind?","vi":"Liệu tôi có bị ép phải thay đổi suy nghĩ của mình không?","ipa":null,"blanks":[],"words":[{"w":"Will","s":221.715,"e":222.03499,"sp":0},{"w":"I","s":222.03499,"e":222.19499,"sp":0},{"w":"be","s":222.19499,"e":222.355,"sp":0},{"w":"forced","s":222.355,"e":222.59499,"sp":0},{"w":"to","s":222.59499,"e":222.75499,"sp":0},{"w":"change","s":222.75499,"e":223.075,"sp":0},{"w":"my","s":223.075,"e":223.39499,"sp":0},{"w":"mind?","s":223.39499,"e":223.955,"sp":0}],"alts":null},{"i":41,"start":224.685,"end":226.235,"text":"Will I be changed?","vi":"Liệu tôi có bị thay đổi không?","ipa":null,"blanks":[],"words":[{"w":"Will","s":224.83499,"e":225.155,"sp":0},{"w":"I","s":225.155,"e":225.39499,"sp":0},{"w":"be","s":225.39499,"e":225.635,"sp":0},{"w":"changed?","s":225.635,"e":226.03499,"sp":0}],"alts":null},{"i":42,"start":227.01,"end":234.06,"text":"At a primal level, it can feel scary to open ourselves up to ideas which clash with our values,","vi":"Ở mức độ bản năng, việc mở lòng với những ý tưởng trái ngược với giá trị của bản thân có thể khiến chúng ta cảm thấy sợ hãi,","ipa":null,"blanks":[],"words":[{"w":"At","s":227.16,"e":227.48,"sp":0},{"w":"a","s":227.48,"e":227.56,"sp":0},{"w":"primal","s":227.56,"e":227.96,"sp":0},{"w":"level,","s":227.96,"e":228.36,"sp":0},{"w":"it","s":228.36,"e":228.52,"sp":0},{"w":"can","s":228.52,"e":228.68001,"sp":0},{"w":"feel","s":228.68001,"e":229.32,"sp":0},{"w":"scary","s":229.32,"e":229.72,"sp":0},{"w":"to","s":229.72,"e":229.96,"sp":0},{"w":"open","s":229.96,"e":230.28,"sp":0},{"w":"ourselves","s":230.28,"e":230.68001,"sp":0},{"w":"up","s":230.68001,"e":231,"sp":0},{"w":"to","s":231,"e":231.16,"sp":0},{"w":"ideas","s":231.16,"e":231.8,"sp":0},{"w":"which","s":231.8,"e":232.12,"sp":0},{"w":"clash","s":232.12,"e":232.6,"sp":0},{"w":"with","s":232.6,"e":232.84,"sp":0},{"w":"our","s":232.84,"e":233.08,"sp":0},{"w":"values,","s":233.08,"e":233.88,"sp":0}],"alts":null},{"i":43,"start":234.13,"end":240.8,"text":"and the result, a world in which we think it''s better, even more moral, to cite","vi":"và kết quả là, chúng ta tạo ra một thế giới mà ở đó, việc trích dẫn lại được coi là tốt hơn, thậm chí là đạo đức hơn.","ipa":null,"blanks":[],"words":[{"w":"and","s":234.28,"e":234.44,"sp":0},{"w":"the","s":234.44,"e":234.68001,"sp":0},{"w":"result,","s":234.68001,"e":235.40001,"sp":0},{"w":"a","s":235.56,"e":235.8,"sp":0},{"w":"world","s":235.8,"e":235.96,"sp":0},{"w":"in","s":235.96,"e":236.2,"sp":0},{"w":"which","s":236.2,"e":236.36,"sp":0},{"w":"we","s":236.36,"e":236.52,"sp":0},{"w":"think","s":236.52,"e":236.76001,"sp":0},{"w":"it''s","s":236.76001,"e":237,"sp":0},{"w":"better,","s":237,"e":237.72002,"sp":0},{"w":"even","s":237.96,"e":238.28,"sp":0},{"w":"more","s":238.28,"e":238.68001,"sp":0},{"w":"moral,","s":238.68001,"e":239.56001,"sp":0},{"w":"to","s":239.64,"e":239.72,"sp":0},{"w":"cite","s":239.72,"e":240.6,"sp":0}],"alts":null}]','["dictation","shadowing"]',NULL,NULL,NULL,NULL,NULL,'dictation_shadowing',NULL,NULL,NULL,'tp_communication_and_language',NULL,NULL,'2026-10-28T00:00:01.000Z',NULL);
INSERT OR IGNORE INTO exercises (id,exercise_id,title,published,skill,level,tags,passage,passage_ipa,audio_url,audio_script,audio_voice,audio_cues,dictation_mode,translate_level,read_aloud,wordlist,vocab_deck,media_source,video,youtube_id,video_lang,video_segments,video_modes,speaking_prompt,speaking_framework,speaking_sample,speaking_image,image,template_id,gen_config,path_order,stage_id,topic_id,tag_id,layer,created_at,deleted_at) VALUES ('seed-video-ted-stop-homelessness','video-ted-stop-homelessness','How to Stop Homelessness Before It Starts (TED)',1,'listening','Pre A1 Starters',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,NULL,NULL,1,'cTHwSER_l-8',NULL,'[{"i":0,"start":4.17,"end":10.74,"text":"About 20 years ago, I was working the front desk of the largest homeless shelter in Silicon Valley,","vi":"Khoảng hai mươi năm trước, tôi làm việc tại quầy lễ tân của trại tạm trú cho người vô gia cư lớn nhất ở Thung lũng Silicon.","ipa":null,"blanks":[],"words":[{"w":"About","s":4.3199997,"e":4.72,"sp":0},{"w":"twenty","s":4.72,"e":5.04,"sp":0},{"w":"years","s":5.04,"e":5.2799997,"sp":0},{"w":"ago,","s":5.2799997,"e":5.92,"sp":0},{"w":"I","s":5.92,"e":6.08,"sp":0},{"w":"was","s":6.08,"e":6.24,"sp":0},{"w":"working","s":6.24,"e":6.48,"sp":0},{"w":"the","s":6.48,"e":6.64,"sp":0},{"w":"front","s":6.64,"e":6.8799996,"sp":0},{"w":"desk","s":6.8799996,"e":7.2799997,"sp":0},{"w":"of","s":7.2799997,"e":7.6,"sp":0},{"w":"the","s":7.6,"e":7.8399997,"sp":0},{"w":"largest","s":7.8399997,"e":8.32,"sp":0},{"w":"homeless","s":8.32,"e":8.72,"sp":0},{"w":"shelter","s":8.72,"e":9.04,"sp":0},{"w":"in","s":9.04,"e":9.36,"sp":0},{"w":"Silicon","s":9.36,"e":9.84,"sp":0},{"w":"Valley,","s":9.84,"e":10.559999,"sp":0}],"alts":{"1":["twenty"]}},{"i":1,"start":10.81,"end":12.92,"text":"and that''s when Tanya walked in.","vi":"Và đó là lúc Tanya bước vào.","ipa":null,"blanks":[],"words":[{"w":"and","s":10.96,"e":11.04,"sp":0},{"w":"that''s","s":11.04,"e":11.28,"sp":0},{"w":"when","s":11.28,"e":11.44,"sp":0},{"w":"Tanya","s":11.44,"e":11.84,"sp":0},{"w":"walked","s":11.84,"e":12.16,"sp":0},{"w":"in.","s":12.16,"e":12.719999,"sp":0}],"alts":null},{"i":2,"start":13.29,"end":19.341,"text":"She looked exhausted, the kind of weary that comes from having no place to go","vi":"Cô ấy trông kiệt sức, cái vẻ mệt mỏi của người không còn nơi nào để đi.","ipa":null,"blanks":[],"words":[{"w":"She","s":13.44,"e":13.679999,"sp":0},{"w":"looked","s":13.679999,"e":14,"sp":0},{"w":"exhausted,","s":14,"e":14.639999,"sp":0},{"w":"the","s":15.545,"e":15.865,"sp":0},{"w":"kind","s":15.865,"e":16.105,"sp":0},{"w":"of","s":16.105,"e":16.185,"sp":0},{"w":"weary","s":16.185,"e":16.585001,"sp":0},{"w":"that","s":16.585001,"e":16.825,"sp":0},{"w":"comes","s":16.825,"e":17.225,"sp":0},{"w":"from","s":17.225,"e":17.465,"sp":0},{"w":"having","s":17.465,"e":17.945,"sp":0},{"w":"no","s":17.945,"e":18.265,"sp":0},{"w":"place","s":18.265,"e":18.585,"sp":0},{"w":"to","s":18.585,"e":18.745,"sp":0},{"w":"go","s":18.745,"e":19.305,"sp":0}],"alts":null},{"i":3,"start":19.349,"end":21.425,"text":"and no idea what to do.","vi":"Và không biết phải làm gì.","ipa":null,"blanks":[],"words":[{"w":"and","s":19.385,"e":19.705,"sp":0},{"w":"no","s":19.705,"e":20.025,"sp":0},{"w":"idea","s":20.025,"e":20.345001,"sp":0},{"w":"what","s":20.345001,"e":20.585,"sp":0},{"w":"to","s":20.585,"e":20.744999,"sp":0},{"w":"do.","s":20.744999,"e":21.225,"sp":0}],"alts":null},{"i":4,"start":22.115,"end":27.505,"text":"She was clutching a satchel tightly to her chest like it was all she had left.","vi":"Cô ấy ôm chặt một chiếc túi vào ngực như thể đó là tất cả những gì cô còn lại.","ipa":null,"blanks":[],"words":[{"w":"She","s":22.265,"e":22.585,"sp":0},{"w":"was","s":22.585,"e":22.744999,"sp":0},{"w":"clutching","s":22.744999,"e":23.305,"sp":0},{"w":"a","s":23.305,"e":23.465,"sp":0},{"w":"satchel","s":23.465,"e":23.945,"sp":0},{"w":"tightly","s":23.945,"e":24.585,"sp":0},{"w":"to","s":24.585,"e":24.744999,"sp":0},{"w":"her","s":24.744999,"e":24.985,"sp":0},{"w":"chest","s":24.985,"e":25.545,"sp":0},{"w":"like","s":25.545,"e":25.865,"sp":0},{"w":"it","s":25.865,"e":26.025,"sp":0},{"w":"was","s":26.025,"e":26.265,"sp":0},{"w":"all","s":26.265,"e":26.505001,"sp":0},{"w":"she","s":26.505001,"e":26.825,"sp":0},{"w":"had","s":26.825,"e":27.064999,"sp":0},{"w":"left.","s":27.064999,"e":27.305,"sp":0}],"alts":null},{"i":5,"start":28.59,"end":32.62,"text":"And then all of a sudden, the satchel started to cry.","vi":"Và rồi đột nhiên, chiếc túi bắt đầu khóc.","ipa":null,"blanks":[],"words":[{"w":"And","s":28.74,"e":29.06,"sp":0},{"w":"then","s":29.06,"e":29.22,"sp":0},{"w":"all","s":29.22,"e":29.380001,"sp":0},{"w":"of","s":29.380001,"e":29.54,"sp":0},{"w":"a","s":29.54,"e":29.7,"sp":0},{"w":"sudden,","s":29.7,"e":30.34,"sp":0},{"w":"the","s":30.5,"e":30.74,"sp":0},{"w":"satchel","s":30.74,"e":31.220001,"sp":0},{"w":"started","s":31.220001,"e":31.62,"sp":0},{"w":"to","s":31.62,"e":31.78,"sp":0},{"w":"cry.","s":31.78,"e":32.42,"sp":0}],"alts":null},{"i":6,"start":33.63,"end":36.06,"text":"Inside was her newborn baby.","vi":"Bên trong là đứa con mới sinh của cô.","ipa":null,"blanks":[],"words":[{"w":"Inside","s":33.78,"e":34.34,"sp":0},{"w":"was","s":34.34,"e":34.58,"sp":0},{"w":"her","s":34.58,"e":34.74,"sp":0},{"w":"newborn","s":34.74,"e":35.14,"sp":0},{"w":"baby.","s":35.14,"e":35.86,"sp":0}],"alts":null},{"i":7,"start":37.71,"end":41.18,"text":"She shared that she had been assaulted, which led to her pregnancy.","vi":"Cô chia sẻ rằng mình đã bị hành hung, dẫn đến việc mang thai.","ipa":null,"blanks":[],"words":[{"w":"She","s":37.86,"e":38.18,"sp":0},{"w":"shared","s":38.18,"e":38.5,"sp":0},{"w":"that","s":38.5,"e":38.66,"sp":0},{"w":"she","s":38.66,"e":38.82,"sp":0},{"w":"had","s":38.82,"e":38.98,"sp":0},{"w":"been","s":38.98,"e":39.14,"sp":0},{"w":"assaulted,","s":39.14,"e":39.86,"sp":0},{"w":"which","s":39.86,"e":39.94,"sp":0},{"w":"led","s":39.94,"e":40.18,"sp":0},{"w":"to","s":40.